<template>
  <el-card><template #header><div class="head"><div><h2>评价管理</h2><p>审核买家评价并公开回复，待审核内容不会展示在商品页。</p></div><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="待审核" value="pending"/><el-option label="已通过" value="approved"/><el-option label="已拒绝" value="rejected"/></el-select></div></template>
    <el-table :data="rows" v-loading="loading" stripe><el-table-column prop="product_title" label="商品" min-width="170"/><el-table-column label="评分" width="90"><template #default="{row}">{{ '★'.repeat(row.rating) }}</template></el-table-column><el-table-column label="买家" width="130"><template #default="{row}">{{ row.reviewer_name }} <el-tag v-if="row.verified_purchase" size="small" type="success">已购</el-tag></template></el-table-column><el-table-column label="评价" min-width="260"><template #default="{row}"><strong>{{ row.title }}</strong><p>{{ row.comment }}</p></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='approved'?'success':row.status==='rejected'?'danger':'warning'">{{ labels[row.status] }}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="edit(row)">处理</el-button></template></el-table-column></el-table>
  </el-card>
  <el-dialog v-model="visible" title="审核与回复" width="540px"><el-form label-position="top"><el-form-item label="审核结果"><el-radio-group v-model="form.status"><el-radio value="approved">通过</el-radio><el-radio value="rejected">拒绝</el-radio><el-radio value="pending">待审核</el-radio></el-radio-group></el-form-item><el-form-item label="商家公开回复"><el-input v-model="form.merchant_reply" type="textarea" :rows="4" maxlength="2000" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import api from '../api';const rows=ref([]),loading=ref(false),status=ref(''),visible=ref(false),saving=ref(false),current=ref(null),form=reactive({status:'approved',merchant_reply:''}),labels={pending:'待审核',approved:'已通过',rejected:'已拒绝'}
async function load(){loading.value=true;try{rows.value=(await api.get('/admin/reviews',{params:{status:status.value||undefined}})).data}catch{ElMessage.error('加载评价失败')}finally{loading.value=false}}
function edit(row){current.value=row;form.status=row.status;form.merchant_reply=row.merchant_reply||'';visible.value=true}async function save(){saving.value=true;try{await api.put(`/admin/reviews/${current.value.id}`,form);ElMessage.success('评价已更新');visible.value=false;await load()}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.head{display:flex;align-items:center;justify-content:space-between}.head h2{margin:0}.head p{margin:6px 0 0;color:#6b7280;font-size:13px}.el-table p{margin:5px 0 0;color:#606266}</style>
